import React, { createContext, useContext, useReducer, ReactNode } from 'react';

interface OGImageState {
  // Pattern settings
  pattern: string;
  patternColor: string;
  patternOpacity: number;
  patternSize: number;

  // Background settings
  backgroundType: 'presets' | 'custom' | 'solid';
  background: string;
  solidColor: string;
  customGradient: {
    start: string;
    end: string;
    direction: string;
  };

  // Content settings
  title: string;
  subtitle: string;
  titleSize: number;
  textAlign: 'left' | 'center' | 'right';
  textColor: string;

  // Image settings
  hasImage: boolean;
  imagePosition: 'left' | 'right' | 'center' | 'background' | undefined;
  imageUrl: string;

  // Template tracking
  appliedTemplate: string | null;
  templateLocked: boolean; // New field to track if template should persist
}

type OGImageAction = 
  | { type: 'SET_PATTERN'; payload: string }
  | { type: 'SET_PATTERN_COLOR'; payload: string }
  | { type: 'SET_PATTERN_OPACITY'; payload: number }
  | { type: 'SET_PATTERN_SIZE'; payload: number }
  | { type: 'SET_BACKGROUND_TYPE'; payload: 'presets' | 'custom' | 'solid' }
  | { type: 'SET_BACKGROUND'; payload: string }
  | { type: 'SET_SOLID_COLOR'; payload: string }
  | { type: 'SET_CUSTOM_GRADIENT'; payload: { start: string; end: string; direction: string } }
  | { type: 'SET_TITLE'; payload: string }
  | { type: 'SET_SUBTITLE'; payload: string }
  | { type: 'SET_TITLE_SIZE'; payload: number }
  | { type: 'SET_TEXT_ALIGN'; payload: 'left' | 'center' | 'right' }
  | { type: 'SET_TEXT_COLOR'; payload: string }
  | { type: 'SET_IMAGE_URL'; payload: string }
  | { type: 'CLEAR_TEMPLATE' } // New action to manually clear template
  | { type: 'APPLY_TEMPLATE'; payload: { 
      id: string; 
      background: string; 
      textColor: string; 
      titleSize: number;
      hasImage?: boolean;
      imagePosition?: 'left' | 'right' | 'center' | 'background';
    } };

const initialState: OGImageState = {
  pattern: 'grid',
  patternColor: '#ffffff',
  patternOpacity: 8,
  patternSize: 20,

  backgroundType: 'presets',
  background: 'linear-gradient(135deg, #667eea 0%, #764ba2 100%)',
  solidColor: '#3b82f6',
  customGradient: {
    start: '#667eea',
    end: '#764ba2',
    direction: '135deg'
  },

  title: 'Create Amazing Content',
  subtitle: 'Design beautiful social media images with ease',
  titleSize: 48,
  textAlign: 'center',
  textColor: '#ffffff',

  hasImage: false,
  imagePosition: undefined,
  imageUrl: '',

  appliedTemplate: null,
  templateLocked: false
};

function ogImageReducer(state: OGImageState, action: OGImageAction): OGImageState {
  switch (action.type) {
    case 'SET_PATTERN':
      return { ...state, pattern: action.payload };
    case 'SET_PATTERN_COLOR':
      return { ...state, patternColor: action.payload };
    case 'SET_PATTERN_OPACITY':
      return { ...state, patternOpacity: action.payload };
    case 'SET_PATTERN_SIZE':
      return { ...state, patternSize: action.payload };
    case 'SET_BACKGROUND_TYPE':
      // When changing background type, maintain the current background if it matches the type
      let newBackground = state.background;
      if (action.payload === 'solid') {
        newBackground = state.solidColor;
      } else if (action.payload === 'custom') {
        newBackground = `linear-gradient(${state.customGradient.direction}, ${state.customGradient.start}, ${state.customGradient.end})`;
      }
      return { ...state, backgroundType: action.payload, background: newBackground };
    case 'SET_BACKGROUND':
      return { ...state, background: action.payload };
    case 'SET_SOLID_COLOR':
      return { 
        ...state, 
        solidColor: action.payload,
        background: state.backgroundType === 'solid' ? action.payload : state.background
      };
    case 'SET_CUSTOM_GRADIENT':
      const newGradient = `linear-gradient(${action.payload.direction}, ${action.payload.start}, ${action.payload.end})`;
      return { 
        ...state, 
        customGradient: action.payload,
        background: state.backgroundType === 'custom' ? newGradient : state.background
      };
    case 'SET_TITLE':
      return { ...state, title: action.payload };
    case 'SET_SUBTITLE':
      return { ...state, subtitle: action.payload };
    case 'SET_TITLE_SIZE':
      return { ...state, titleSize: action.payload };
    case 'SET_TEXT_ALIGN':
      return { ...state, textAlign: action.payload };
    case 'SET_TEXT_COLOR':
      return { ...state, textColor: action.payload };
    case 'SET_IMAGE_URL':
      return { ...state, imageUrl: action.payload };
    case 'CLEAR_TEMPLATE':
      return { 
        ...state, 
        appliedTemplate: null, 
        templateLocked: false,
        hasImage: false,
        imagePosition: undefined 
      };
    case 'APPLY_TEMPLATE':
      return {
        ...state,
        background: action.payload.background,
        textColor: action.payload.textColor,
        titleSize: action.payload.titleSize,
        backgroundType: 'presets',
        appliedTemplate: action.payload.id,
        templateLocked: true, // Lock the template when applied
        hasImage: action.payload.hasImage || false,
        imagePosition: action.payload.imagePosition
      };
    default:
      return state;
  }
}

const OGImageContext = createContext<{
  state: OGImageState;
  dispatch: React.Dispatch<OGImageAction>;
} | undefined>(undefined);

export function OGImageProvider({ children }: { children: ReactNode }) {
  const [state, dispatch] = useReducer(ogImageReducer, initialState);

  return (
    <OGImageContext.Provider value={{ state, dispatch }}>
      {children}
    </OGImageContext.Provider>
  );
}

export function useOGImage() {
  const context = useContext(OGImageContext);
  if (context === undefined) {
    throw new Error('useOGImage must be used within an OGImageProvider');
  }
  return context;
}

import React from 'react';
import { Info } from 'lucide-react';
import { useOGImage } from '../contexts/OGImageContext';

const presetGradients = [
  { name: 'Ocean', gradient: 'linear-gradient(135deg, #667eea 0%, #764ba2 100%)' },
  { name: 'Sunset', gradient: 'linear-gradient(135deg, #f093fb 0%, #f5576c 100%)' },
  { name: 'Forest', gradient: 'linear-gradient(135deg, #4facfe 0%, #00f2fe 100%)' },
  { name: 'Purple', gradient: 'linear-gradient(135deg, #a8edea 0%, #fed6e3 100%)' },
  { name: 'Orange', gradient: 'linear-gradient(135deg, #ff9a9e 0%, #fecfef 100%)' },
  { name: 'Blue', gradient: 'linear-gradient(135deg, #a1c4fd 0%, #c2e9fb 100%)' },
];

export function BackgroundControls() {
  const { state, dispatch } = useOGImage();

  const handlePresetSelect = (gradient: string) => {
    dispatch({ type: 'SET_BACKGROUND', payload: gradient });
    // Ensure we're in presets mode when selecting a preset
    if (state.backgroundType !== 'presets') {
      dispatch({ type: 'SET_BACKGROUND_TYPE', payload: 'presets' });
    }
  };

  return (
    <div className="space-y-6">
      <div className="flex items-center space-x-2">
        <h3 className="text-lg font-semibold">Background</h3>
        <Info className="w-4 h-4 text-gray-500" />
      </div>

      {/* Background Type Tabs */}
      <div className="flex rounded-lg bg-gray-800/50 p-1">
        {['presets', 'custom', 'solid'].map((type) => (
          <button
            key={type}
            onClick={() => dispatch({ type: 'SET_BACKGROUND_TYPE', payload: type as "presets" | "custom" | "solid" })}
            className={`flex-1 px-4 py-2 rounded-md text-sm font-medium transition-all duration-200 ${
              state.backgroundType === type
                ? 'bg-blue-600 text-white shadow-lg'
                : 'text-gray-400 hover:text-white hover:bg-gray-700/50'
            }`}
          >
            {type.charAt(0).toUpperCase() + type.slice(1)}
          </button>
        ))}
      </div>

      {/* Preset Gradients */}
      {state.backgroundType === 'presets' && (
        <div className="grid grid-cols-2 gap-3">
          {presetGradients.map((preset) => (
            <button
              key={preset.name}
              onClick={() => handlePresetSelect(preset.gradient)}
              className={`h-16 rounded-lg border-2 transition-all duration-200 hover:scale-105 ${
                state.background === preset.gradient
                  ? 'border-blue-500 ring-2 ring-blue-500/30'
                  : 'border-gray-600 hover:border-gray-500'
              }`}
              style={{ background: preset.gradient }}
            >
              <span className="text-white text-sm font-medium bg-black/20 px-2 py-1 rounded">
                {preset.name}
              </span>
            </button>
          ))}
        </div>
      )}

      {/* Custom Gradient */}
      {state.backgroundType === 'custom' && (
        <div className="space-y-4">
          <div className="space-y-3">
            <label className="block text-sm font-medium text-gray-300">Start Color</label>
            <input
              type="color"
              value={state.customGradient.start}
              onChange={(e) => dispatch({ 
                type: 'SET_CUSTOM_GRADIENT', 
                payload: { ...state.customGradient, start: e.target.value }
              })}
              className="w-full h-12 rounded-lg border border-gray-600 bg-gray-700 cursor-pointer"
            />
          </div>

          <div className="space-y-3">
            <label className="block text-sm font-medium text-gray-300">End Color</label>
            <input
              type="color"
              value={state.customGradient.end}
              onChange={(e) => dispatch({ 
                type: 'SET_CUSTOM_GRADIENT', 
                payload: { ...state.customGradient, end: e.target.value }
              })}
              className="w-full h-12 rounded-lg border border-gray-600 bg-gray-700 cursor-pointer"
            />
          </div>

          <div className="space-y-3">
            <label className="block text-sm font-medium text-gray-300">Direction</label>
            <select
              value={state.customGradient.direction}
              onChange={(e) => dispatch({ 
                type: 'SET_CUSTOM_GRADIENT', 
                payload: { ...state.customGradient, direction: e.target.value }
              })}
              className="w-full px-3 py-2 bg-gray-700 border border-gray-600 rounded-lg text-white focus:outline-none focus:ring-2 focus:ring-blue-500"
            >
              <option value="135deg">Diagonal ↗</option>
              <option value="90deg">Vertical ↑</option>
              <option value="0deg">Horizontal →</option>
              <option value="45deg">Diagonal ↖</option>
            </select>
          </div>
        </div>
      )}

      {/* Solid Color */}
      {state.backgroundType === 'solid' && (
        <div className="space-y-3">
          <label className="block text-sm font-medium text-gray-300">Solid Color</label>
          <input
            type="color"
            value={state.solidColor}
            onChange={(e) => dispatch({ type: 'SET_SOLID_COLOR', payload: e.target.value })}
            className="w-full h-12 rounded-lg border border-gray-600 bg-gray-700 cursor-pointer"
          />
        </div>
      )}
    </div>
  );
}

import { clsx, type ClassValue } from "clsx"
import { twMerge } from "tailwind-merge"

export function cn(...inputs: ClassValue[]) {
  return twMerge(clsx(inputs))
}

import React from 'react';
import { Grid, Circle, Hash, Minus, Hexagon, Zap, Info, Sparkles, Waves, Layers } from 'lucide-react';
import { useOGImage } from '../contexts/OGImageContext';

const patterns = [
  { id: 'grid', name: 'Grid', icon: Grid, type: 'basic' },
  { id: 'dots', name: 'Dots', icon: Circle, type: 'basic' },
  { id: 'graph', name: 'Graph', icon: Hash, type: 'basic' },
  { id: 'lines', name: 'Lines', icon: Minus, type: 'basic' },
  { id: 'hex', name: 'Hex', icon: Hexagon, type: 'basic' },
  { id: 'noise', name: 'Noise', icon: Zap, type: 'basic' },
  { id: 'warp', name: 'Warp', icon: Layers, type: 'advanced' },
  { id: 'flickering', name: 'Flicker', icon: Sparkles, type: 'advanced' },
  { id: 'retro', name: 'Retro', icon: Waves, type: 'advanced' },
  { id: 'animated-dots', name: 'Glow Dots', icon: Circle, type: 'advanced' },
];

export function PatternOverlay() {
  const { state, dispatch } = useOGImage();

  const basicPatterns = patterns.filter(p => p.type === 'basic');
  const advancedPatterns = patterns.filter(p => p.type === 'advanced');

  return (
    <div className="space-y-6">
      <div className="flex items-center space-x-2">
        <h3 className="text-lg font-semibold">Pattern Overlay</h3>
        <Info className="w-4 h-4 text-gray-500" />
      </div>

      {/* Basic Patterns */}
      <div className="space-y-3">
        <h4 className="text-sm font-medium text-gray-300">Basic Patterns</h4>
        <div className="grid grid-cols-3 gap-3">
          {basicPatterns.map((pattern) => {
            const Icon = pattern.icon;
            return (
              <button
                key={pattern.id}
                onClick={() => dispatch({ type: 'SET_PATTERN', payload: pattern.id })}
                className={`p-4 rounded-xl border-2 transition-all duration-200 hover:scale-105 ${
                  state.pattern === pattern.id
                    ? 'border-blue-500 bg-blue-500/20 text-blue-400'
                    : 'border-gray-600 bg-gray-800/50 text-gray-400 hover:border-gray-500 hover:text-gray-300'
                }`}
              >
                <Icon className="w-6 h-6 mx-auto mb-2" />
                <span className="text-sm font-medium">{pattern.name}</span>
              </button>
            );
          })}
        </div>
      </div>

      {/* Advanced Patterns */}
      <div className="space-y-3">
        <div className="flex items-center space-x-2">
          <h4 className="text-sm font-medium text-gray-300">Advanced Patterns</h4>
          <Sparkles className="w-4 h-4 text-yellow-400" />
        </div>
        <div className="grid grid-cols-2 gap-3">
          {advancedPatterns.map((pattern) => {
            const Icon = pattern.icon;
            return (
              <button
                key={pattern.id}
                onClick={() => dispatch({ type: 'SET_PATTERN', payload: pattern.id })}
                className={`p-4 rounded-xl border-2 transition-all duration-200 hover:scale-105 ${
                  state.pattern === pattern.id
                    ? 'border-blue-500 bg-blue-500/20 text-blue-400'
                    : 'border-gray-600 bg-gray-800/50 text-gray-400 hover:border-gray-500 hover:text-gray-300'
                }`}
              >
                <Icon className="w-6 h-6 mx-auto mb-2" />
                <span className="text-sm font-medium">{pattern.name}</span>
                <div className="text-xs text-yellow-400 mt-1">Animated</div>
              </button>
            );
          })}
        </div>
      </div>

      {/* Pattern Color */}
      <div className="space-y-3">
        <label className="block text-sm font-medium text-gray-300">Pattern Color</label>
        <div className="flex items-center space-x-3">
          <input
            type="color"
            value={state.patternColor}
            onChange={(e) => dispatch({ type: 'SET_PATTERN_COLOR', payload: e.target.value })}
            className="w-12 h-12 rounded-lg border border-gray-600 bg-gray-700 cursor-pointer"
          />
          <input
            type="text"
            value={state.patternColor}
            onChange={(e) => dispatch({ type: 'SET_PATTERN_COLOR', payload: e.target.value })}
            className="flex-1 px-3 py-2 bg-gray-700 border border-gray-600 rounded-lg text-white placeholder-gray-400 focus:outline-none focus:ring-2 focus:ring-blue-500"
            placeholder="#ffffff"
          />
        </div>
      </div>

      {/* Opacity Slider */}
      <div className="space-y-3">
        <div className="flex items-center justify-between">
          <label className="text-sm font-medium text-gray-300">Opacity</label>
          <span className="text-sm text-gray-400">{state.patternOpacity}%</span>
        </div>
        <input
          type="range"
          min="0"
          max="100"
          value={state.patternOpacity}
          onChange={(e) => dispatch({ type: 'SET_PATTERN_OPACITY', payload: parseInt(e.target.value) })}
          className="w-full h-2 bg-gray-700 rounded-lg appearance-none cursor-pointer slider"
        />
      </div>

      {/* Pattern Size */}
      <div className="space-y-3">
        <div className="flex items-center justify-between">
          <label className="text-sm font-medium text-gray-300">Pattern Size</label>
          <span className="text-sm text-gray-400">{state.patternSize}px</span>
        </div>
        <input
          type="range"
          min="10"
          max="100"
          value={state.patternSize}
          onChange={(e) => dispatch({ type: 'SET_PATTERN_SIZE', payload: parseInt(e.target.value) })}
          className="w-full h-2 bg-gray-700 rounded-lg appearance-none cursor-pointer slider"
        />
      </div>
    </div>
  );
