import { useRef } from 'react';
import { Download, Eye } from 'lucide-react';
import { useOGImage } from '../contexts/OGImageContext';
import { WarpBackground } from './patterns/WarpBackground';
import { FlickeringGrid } from './patterns/FlickeringGrid';
import { RetroGrid } from './patterns/RetroGrid';
import { DotPattern } from './patterns/DotPattern';
import html2canvas from 'html2canvas';

export function PreviewPanel() {
  const { state } = useOGImage();
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const previewRef = useRef<HTMLDivElement>(null);

  const getBackground = () => {
    if (state.backgroundType === 'solid') {
      return state.solidColor;
    } else if (state.backgroundType === 'custom') {
      return `linear-gradient(${state.customGradient.direction}, ${state.customGradient.start}, ${state.customGradient.end})`;
    }
    return state.background;
  };

  const getPatternSvg = () => {
    const size = state.patternSize;
    const color = state.patternColor;

    switch (state.pattern) {
      case 'grid':
        return `data:image/svg+xml,${encodeURIComponent(`
          <svg width="${size}" height="${size}" xmlns="http://www.w3.org/2000/svg">
            <rect width="${size}" height="${size}" fill="none" stroke="${color}" stroke-width="1"/>
          </svg>
        `)}`;
      case 'dots':
        return `data:image/svg+xml,${encodeURIComponent(`
          <svg width="${size}" height="${size}" xmlns="http://www.w3.org/2000/svg">
            <circle cx="${size/2}" cy="${size/2}" r="2" fill="${color}"/>
          </svg>
        `)}`;
      case 'graph':
        return `data:image/svg+xml,${encodeURIComponent(`
          <svg width="${size}" height="${size}" xmlns="http://www.w3.org/2000/svg">
            <rect width="${size}" height="${size}" fill="none" stroke="${color}" stroke-width="1"/>
            <line x1="0" y1="${size/2}" x2="${size}" y2="${size/2}" stroke="${color}" stroke-width="0.5"/>
            <line x1="${size/2}" y1="0" x2="${size/2}" y2="${size}" stroke="${color}" stroke-width="0.5"/>
          </svg>
        `)}`;
      case 'lines':
        return `data:image/svg+xml,${encodeURIComponent(`
          <svg width="${size}" height="${size}" xmlns="http://www.w3.org/2000/svg">
            <line x1="0" y1="${size/2}" x2="${size}" y2="${size/2}" stroke="${color}" stroke-width="1"/>
          </svg>
        `)}`;
      case 'hex':
        return `data:image/svg+xml,${encodeURIComponent(`
          <svg width="${size}" height="${size}" xmlns="http://www.w3.org/2000/svg">
            <polygon points="${size/2},2 ${size-2},${size/4} ${size-2},${3*size/4} ${size/2},${size-2} 2,${3*size/4} 2,${size/4}" 
                     fill="none" stroke="${color}" stroke-width="1"/>
          </svg>
        `)}`;
      case 'noise':
        return `data:image/svg+xml,${encodeURIComponent(`
          <svg width="${size}" height="${size}" xmlns="http://www.w3.org/2000/svg">
            <circle cx="${size/4}" cy="${size/4}" r="0.5" fill="${color}"/>
            <circle cx="${3*size/4}" cy="${size/4}" r="0.5" fill="${color}"/>
            <circle cx="${size/2}" cy="${size/2}" r="0.5" fill="${color}"/>
            <circle cx="${size/4}" cy="${3*size/4}" r="0.5" fill="${color}"/>
            <circle cx="${3*size/4}" cy="${3*size/4}" r="0.5" fill="${color}"/>
          </svg>
        `)}`;
      default:
        return '';
    }
  };

  const renderAdvancedPattern = () => {
    const opacity = state.patternOpacity / 100;
    const color = state.patternColor;

    switch (state.pattern) {
      case 'warp':
        return (
          <div className="absolute inset-0 pointer-events-none" style={{ opacity }}>
            <WarpBackground
              perspective={100}
              beamsPerSide={3}
              beamSize={state.patternSize / 10}
              gridColor={`${color}40`}
              className="w-full h-full"
            >
              <div />
            </WarpBackground>
          </div>
        );

      case 'flickering':
        return (
          <div className="absolute inset-0 pointer-events-none" style={{ opacity }}>
            <FlickeringGrid
              squareSize={state.patternSize / 10}
              gridGap={state.patternSize / 8}
              flickerChance={0.3}
              color={color}
              maxOpacity={0.8}
              className="w-full h-full"
            />
          </div>
        );

      case 'retro':
        return (
          <div className="absolute inset-0 pointer-events-none" style={{ opacity }}>
            <RetroGrid
              angle={65}
              cellSize={state.patternSize}
              opacity={1}
              lightLineColor={color}
              darkLineColor={color}
              className="w-full h-full"
            />
          </div>
        );

      case 'animated-dots':
        return (
          <div className="absolute inset-0 pointer-events-none" style={{ opacity, color }}>
            <DotPattern
              width={state.patternSize}
              height={state.patternSize}
              cr={2}
              glow={true}
              className="w-full h-full"
            />
          </div>
        );

      default:
        return null;
    }
  };

  const downloadImage = async () => {
    const previewElement = previewRef.current;
    if (!previewElement) return;

    try {
      // Use html2canvas to capture the preview content
      const canvas = await html2canvas(previewElement, {
        scale: 2, // Higher scale for better quality
        useCORS: true, // Enable CORS for images
        backgroundColor: null, // Preserve transparency
        logging: false
      });

      // Create download link
      const link = document.createElement('a');
      link.download = 'og-image.png';
      link.href = canvas.toDataURL('image/png');
      link.click();
    } catch (error) {
      console.error('Error generating image:', error);
    }
  };

  const renderContent = () => {
    if (!state.hasImage || !state.imagePosition) {
      // Standard text-only layout
      return (
        <div className={`absolute inset-0 flex flex-col justify-center p-16 text-${state.textAlign}`}>
          <h1
            className="font-bold leading-tight mb-4"
            style={{
              fontSize: `${state.titleSize * 0.8}px`,
              color: state.textColor,
            }}
          >
            {state.title || 'Your Amazing Title'}
          </h1>
          {state.subtitle && (
            <p
              className="text-lg opacity-90"
              style={{
                color: state.textColor,
                fontSize: `${state.titleSize * 0.4}px`,
              }}
            >
              {state.subtitle}
            </p>
          )}
        </div>
      );
    }

    // Image-based layouts
    switch (state.imagePosition) {
      case 'right':
        return (
          <div className="absolute inset-0 flex">
            <div className="flex-1 flex items-center justify-start p-16">
              <div className="text-left">
                <h1
                  className="font-bold leading-tight mb-4"
                  style={{
                    fontSize: `${state.titleSize * 0.7}px`,
                    color: state.textColor,
                  }}
                >
                  {state.title || 'Your Amazing Title'}
                </h1>
                {state.subtitle && (
                  <p
                    className="text-lg opacity-90"
                    style={{
                      color: state.textColor,
                      fontSize: `${state.titleSize * 0.35}px`,
                    }}
                  >
                    {state.subtitle}
                  </p>
                )}
              </div>
            </div>
            <div className="w-[80%] -mr-[10rem] flex items-center justify-center p-8">
              {state.imageUrl ? (
                <img
                  src={state.imageUrl}
                  alt="Content"
                  className="rounded-lg shadow-2xl"
                />
              ) : (
                <div className="w-full h-64 bg-white/20 rounded-lg flex items-center justify-center">
                  <span className="text-white/60 text-lg">Image Placeholder</span>
                </div>
              )}
            </div>
          </div>
        );

      case 'left':
        return (
          <div className="absolute inset-0 flex">
            <div className="w-80 flex items-center justify-center p-8">
              {state.imageUrl ? (
                <img
                  src={state.imageUrl}
                  alt="Content"
                  className="max-w-full max-h-full object-contain rounded-lg shadow-2xl"
                />
              ) : (
                <div className="w-full h-64 bg-white/20 rounded-lg flex items-center justify-center">
                  <span className="text-white/60 text-lg">Image Placeholder</span>
                </div>
              )}
            </div>
            <div className="flex-1 flex items-center justify-start p-16">
              <div className="text-left">
                <h1
                  className="font-bold leading-tight mb-4"
                  style={{
                    fontSize: `${state.titleSize * 0.7}px`,
                    color: state.textColor,
                  }}
                >
                  {state.title || 'Your Amazing Title'}
                </h1>
                {state.subtitle && (
                  <p
                    className="text-lg opacity-90"
                    style={{
                      color: state.textColor,
                      fontSize: `${state.titleSize * 0.35}px`,
                    }}
                  >
                    {state.subtitle}
                  </p>
                )}
              </div>
            </div>
          </div>
        );

      case 'center':
        return (
          <div className="absolute inset-0 flex flex-col">
            <div className="flex-1 p-2 flex items-end justify-center">
              {state.imageUrl ? (
                <img
                  src={state.imageUrl}
                  alt="Content"
                  className="max-h-52 object-contain rounded-lg shadow-2xl"
                />
              ) : (
                <div className="w-64 h-40 bg-white/20 rounded-lg flex items-center justify-center">
                  <span className="text-white/60">Image Placeholder</span>
                </div>
              )}
            </div>
            <div className="flex items-center justify-center p-8">
              <div className="text-center">
                <h1
                  className="font-bold leading-tight mb-4"
                  style={{
                    fontSize: `${state.titleSize * 0.7}px`,
                    color: state.textColor,
                  }}
                >
                  {state.title || 'Your Amazing Title'}
                </h1>
                {state.subtitle && (
                  <p
                    className="text-lg opacity-90"
                    style={{
                      color: state.textColor,
                      fontSize: `${state.titleSize * 0.35}px`,
                    }}
                  >
                    {state.subtitle}
                  </p>
                )}
              </div>
            </div>
          </div>
        );

      case 'background':
        return (
          <div className="absolute inset-0">
            {state.imageUrl && (
              <img
                src={state.imageUrl}
                alt="Background"
                className="absolute inset-0 w-full h-full object-cover"
              />
            )}
            <div className="absolute inset-0 bg-gradient-to-r from-black/60 via-black/40 to-black/60"></div>
            <div className="absolute inset-0 flex items-center justify-center p-16">
              <div className="text-center">
                <h1
                  className="font-bold leading-tight mb-4 drop-shadow-lg"
                  style={{
                    fontSize: `${state.titleSize * 0.8}px`,
                    color: state.textColor,
                  }}
                >
                  {state.title || 'Your Amazing Title'}
                </h1>
                {state.subtitle && (
                  <p
                    className="text-lg opacity-90 drop-shadow-lg"
                    style={{
                      color: state.textColor,
                      fontSize: `${state.titleSize * 0.4}px`,
                    }}
                  >
                    {state.subtitle}
                  </p>
                )}
              </div>
            </div>
          </div>
        );

      default:
        return renderContent();
    }
  };

  const isAdvancedPattern = ['warp', 'flickering', 'retro', 'animated-dots'].includes(state.pattern);

  return (
    <div className="space-y-6">
      <div className="flex items-center justify-between">
        <div className="flex items-center space-x-2">
          <Eye className="w-5 h-5 text-blue-400" />
          <h3 className="text-lg font-semibold">Preview</h3>
          {state.hasImage && (
            <span className="px-2 py-1 bg-green-600/20 text-green-400 text-xs rounded-full">
              Image Layout
            </span>
          )}
          {isAdvancedPattern && (
            <span className="px-2 py-1 bg-yellow-600/20 text-yellow-400 text-xs rounded-full">
              Animated Pattern
            </span>
          )}
        </div>
        <button
          onClick={downloadImage}
          className="flex items-center space-x-2 px-4 py-2 bg-blue-600 hover:bg-blue-700 rounded-lg transition-colors"
        >
          <Download className="w-4 h-4" />
          <span>Download</span>
        </button>
      </div>

      {/* Preview Container */}
      <div className="bg-gray-800/50 backdrop-blur-sm rounded-2xl border border-gray-700/50 p-6">
        <div
          ref={previewRef}
          className="aspect-[1200/630] w-full max-w-2xl mx-auto relative overflow-hidden rounded-xl shadow-2xl"
        >
          {/* Background Layer */}
          <div
            className="absolute inset-0 w-full h-full"
            style={{
              background: getBackground(),
            }}
          />

          {/* Pattern Overlay Layer */}
          {isAdvancedPattern ? (
            renderAdvancedPattern()
          ) : (
            getPatternSvg() && (
              <div
                className="absolute inset-0 w-full h-full pointer-events-none"
                style={{
                  backgroundImage: `url("${getPatternSvg()}")`,
                  backgroundSize: `${state.patternSize}px ${state.patternSize}px`,
                  backgroundRepeat: 'repeat',
                  opacity: state.patternOpacity / 100,
                }}
              />
            )
          )}

          {/* Content Layer */}
          {renderContent()}
        </div>

        {/* Canvas for export */}
        <canvas
          ref={canvasRef}
          width={1200}
          height={630}
          className="hidden"
        />
      </div>

      {/* Dimensions Info */}
      <div className="text-center text-sm text-gray-400">
        <p>OG Image dimensions: 1200 × 630 pixels</p>
        <p>Perfect for Facebook, Twitter, LinkedIn, and other social platforms</p>
        {isAdvancedPattern && (
          <p className="text-yellow-400 mt-1">✨ Advanced animated patterns for stunning visual effects</p>
        )}
      </div>
    </div>
  );
}

