        titleSize: template.titleSize,
        hasImage: template.hasImage,
        imagePosition: template.imagePosition as "right" | "background" | "center" | "left" | undefined
      }
    });
  };

  const clearTemplate = () => {
    dispatch({ type: 'CLEAR_TEMPLATE' });
  };

  const nextTemplates = () => {
    setCurrentIndex((prev) => (prev + 3) % templates.length);
  };

  const prevTemplates = () => {
    setCurrentIndex((prev) => (prev - 3 + templates.length) % templates.length);
  };

  const visibleTemplates = templates.slice(currentIndex, currentIndex + 3);

  const renderTemplatePreview = (template: typeof templates[0]) => {
    if (!template.hasImage) {
      return (
        <div className="absolute inset-0 flex items-center justify-center">
          <div className="text-center px-4">
            <h4
              className="font-bold leading-tight"
              style={{
                color: template.textColor,
                fontSize: `${template.titleSize * 0.25}px`,
              }}
            >
              {template.name}
            </h4>
            <p
              className="text-sm opacity-80 mt-1"
              style={{
                color: template.textColor,
                fontSize: `${template.titleSize * 0.12}px`,
              }}
            >
              {template.description}
            </p>
          </div>
        </div>
      );
    }

    // Templates with images
    switch (template.imagePosition) {
      case 'right':
        return (
          <div className="absolute inset-0 flex">
            <div className="flex-1 flex items-center justify-center p-3">
              <div className="text-left">
                <h4
                  className="font-bold leading-tight"
                  style={{
                    color: template.textColor,
                    fontSize: `${template.titleSize * 0.2}px`,
                  }}
                >
                  {template.name}
                </h4>
                <p
                  className="text-xs opacity-80 mt-1"
                  style={{
                    color: template.textColor,
                    fontSize: `${template.titleSize * 0.1}px`,
                  }}
                >
                  {template.description}
                </p>
              </div>
            </div>
            <div className="w-16 bg-white/20 rounded-lg m-2 flex items-center justify-center">
              <div className="w-8 h-8 bg-white/30 rounded"></div>
            </div>
          </div>
        );

      case 'left':
        return (
          <div className="absolute inset-0 flex">
            <div className="w-16 bg-white/20 rounded-lg m-2 flex items-center justify-center">
              <div className="w-8 h-8 bg-white/30 rounded"></div>
            </div>
            <div className="flex-1 flex items-center justify-center p-3">
              <div className="text-left">
                <h4
                  className="font-bold leading-tight"
                  style={{
                    color: template.textColor,
                    fontSize: `${template.titleSize * 0.2}px`,
                  }}
                >
                  {template.name}
                </h4>
                <p
                  className="text-xs opacity-80 mt-1"
                  style={{
                    color: template.textColor,
                    fontSize: `${template.titleSize * 0.1}px`,
                  }}
                >
                  {template.description}
                </p>
              </div>
            </div>
          </div>
        );

      case 'center':
        return (
          <div className="absolute inset-0 flex flex-col">
            <div className="flex-1 flex items-end justify-center pb-2">
              <div className="w-12 h-8 bg-white/30 rounded"></div>
            </div>
            <div className="flex items-center justify-center p-2">
              <div className="text-center">
                <h4
                  className="font-bold leading-tight"
                  style={{
                    color: template.textColor,
                    fontSize: `${template.titleSize * 0.18}px`,
                  }}
                >
                  {template.name}
                </h4>
              </div>
            </div>
          </div>
        );

      case 'background':
        return (
          <div className="absolute inset-0">
            <div className="absolute inset-0 bg-gradient-to-r from-black/60 to-transparent"></div>
            <div className="absolute inset-0 flex items-center justify-center">
              <div className="text-center px-4">
                <h4
                  className="font-bold leading-tight"
                  style={{
                    color: template.textColor,
                    fontSize: `${template.titleSize * 0.22}px`,
                  }}
                >
                  {template.name}
                </h4>
                <p
                  className="text-xs opacity-90 mt-1"
                  style={{
                    color: template.textColor,
                    fontSize: `${template.titleSize * 0.1}px`,
                  }}
                >
                  {template.description}
                </p>
              </div>
            </div>
            {/* Simulated background pattern */}
            <div className="absolute inset-0 opacity-20">
              <div className="w-full h-full bg-gradient-to-br from-white/10 to-transparent"></div>
            </div>
          </div>
        );

      default:
        return renderTemplatePreview({ ...template, hasImage: false });
    }
  };

  return (
    <div className="space-y-6">
      <div className="flex items-center justify-between">
        <div className="flex items-center space-x-2">
          <Sparkles className="w-5 h-5 text-yellow-400" />
          <h3 className="text-lg font-semibold">Templates</h3>
          <span className="text-sm text-gray-400">({templates.length} available)</span>

          {/* Active Template Indicator */}
          {state.appliedTemplate && (
            <div className="flex items-center space-x-2 ml-4">
              <div className="px-3 py-1 bg-blue-600/20 border border-blue-500/30 rounded-full flex items-center space-x-2">
                <span className="text-blue-400 text-sm font-medium">
                  {templates.find(t => t.id === state.appliedTemplate)?.name || 'Custom Template'}
                </span>
                <button
                  onClick={clearTemplate}
                  className="text-blue-400 hover:text-blue-300 transition-colors"
                  title="Clear template"
                >
                  <X className="w-3 h-3" />
                </button>
              </div>
            </div>
          )}
        </div>

        <div className="flex items-center space-x-2">
          <button
            onClick={prevTemplates}
            className="p-2 bg-gray-800 hover:bg-gray-700 rounded-lg transition-colors"
          >
            <ArrowLeft className="w-4 h-4" />
          </button>
          <span className="text-sm text-gray-400">
            {Math.floor(currentIndex / 3) + 1} / {Math.ceil(templates.length / 3)}
          </span>
          <button
            onClick={nextTemplates}
            className="p-2 bg-gray-800 hover:bg-gray-700 rounded-lg transition-colors"
          >
            <ArrowRight className="w-4 h-4" />
          </button>
        </div>
      </div>

      <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
        {visibleTemplates.map((template) => (
          <div
            key={template.id}
            className={`bg-gray-800/50 backdrop-blur-sm rounded-xl border-2 overflow-hidden hover:scale-105 transition-all duration-200 cursor-pointer ${
              state.appliedTemplate === template.id
                ? 'border-blue-500 ring-2 ring-blue-500/30'
                : 'border-gray-700/50 hover:border-gray-600'
            }`}
            onClick={() => applyTemplate(template)}
          >
            <div
              className="h-32 relative"
              style={{ background: template.background }}
            >
              {renderTemplatePreview(template)}

              {state.appliedTemplate === template.id && (
                <div className="absolute top-2 right-2">
                  <div className="w-6 h-6 bg-blue-500 rounded-full flex items-center justify-center">
                    <div className="w-2 h-2 bg-white rounded-full"></div>
                  </div>
                </div>
              )}
            </div>

            <div className="p-4">
              <div className="flex items-center justify-between">
                <div>
                  <h4 className="font-medium text-white">{template.name}</h4>
                  <p className="text-sm text-gray-400">{template.description}</p>
                </div>
                <div className="flex flex-col items-end space-y-1">
                  <span className="px-2 py-1 bg-blue-600/20 text-blue-400 text-xs rounded-full">
                    {template.category}
                  </span>
                  {template.hasImage && (
                    <span className="px-2 py-1 bg-green-600/20 text-green-400 text-xs rounded-full">
                      Image
                    </span>
                  )}
                </div>
              </div>
            </div>
          </div>
        ))}
      </div>
    </div>
  );
}

